/* Editorial layer: the original palette and application behavior are preserved. */
:root {
  --shadow: 0 8px 28px rgba(75, 56, 35, .045);
  --radius: 18px;
}
body { background: var(--paper); }
::selection { background: var(--sage2); color: var(--ink); }
button, input, textarea, select { -webkit-tap-highlight-color: transparent; }
button { transition: background .2s, box-shadow .2s, transform .2s; }
button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible, summary:focus-visible {
  outline: 2px solid #5d755f;
  outline-offset: 4px;
}
.topbar { background: rgba(247, 242, 232, .96); }
.topbar-inner { max-width: 1240px; padding: 19px 32px; }
.brand { display: flex; align-items: center; gap: 12px; border: 0; padding: 0; background: none; color: var(--ink); text-align: left; font-size: 23px; }
.brand small { display: block; font: 10px var(--sans); letter-spacing: .1em; color: var(--muted); margin-top: 5px; }
.brand-mark { display: grid; place-items: center; width: 43px; height: 48px; border: 1px solid var(--gold); border-radius: 14px 14px 5px 5px; color: #8d7655; font-size: 30px; }
.top-actions { align-items: center; gap: 16px; }
.icon-btn { background: transparent; border-radius: 50%; }
.privacy-badge { background: transparent; }
main { max-width: 1180px; padding: 38px 32px 136px; }
h1, h2, h3 { letter-spacing: -.035em; }
h2 { font-size: clamp(30px, 3.4vw, 42px); }
p { line-height: 1.75; }
.eyebrow { font-size: 10px; letter-spacing: .17em; color: #8d7655; }
.hero { grid-template-columns: 1.2fr 1fr; align-items: center; gap: 38px; margin: 0 0 40px; padding: 18px 0 36px; border-bottom: 1px solid var(--line); }
.hero-copy { background: none; border: 0; border-radius: 12px; box-shadow: none; padding: 16px; }
.hero-copy .eyebrow { display: flex; align-items: center; gap: 12px; }
.hero-copy .eyebrow::before { content: ''; width: 27px; height: 1px; background: var(--gold); }
.hero h1 { font-size: clamp(45px, 5.5vw, 72px); line-height: 1.06; margin: 23px 0; max-width: 600px; }
.hero h1 em { font-weight: 400; color: #5d755f; }
.hero-copy p { font-size: 16px; color: var(--muted); max-width: 460px; margin-bottom: 28px; }
.hero-copy .btn-row { gap: 12px; }
.btn { border-radius: 9px; padding: 13px 19px; font-size: 13px; font-weight: 600; background: var(--sage); color: var(--ink); }
.btn:hover { transform: translateY(-2px); box-shadow: 0 5px 14px #3c30261a; }
.btn.secondary { background: transparent; }
.hero-copy .btn:first-child { background: #5d755f; color: var(--paper2); }
.hero-copy .btn:first-child::after { content: ' ↗'; margin-left: 14px; }
.hero-art { min-height: 420px; display: flex; align-items: center; justify-content: center; background: none; overflow: visible; padding: 22px 20px 42px; }
.hero-art::after { display: none; }
.hero-orbit { position: absolute; width: 90%; aspect-ratio: 1; max-width: 400px; border-radius: 50%; background: var(--sage2); opacity: .65; }
.hero-orbit::after { content: ''; position: absolute; inset: -14px; border: 1px solid var(--line); border-radius: 50%; }
.hero-art img { position: relative; width: 238px; height: auto; aspect-ratio: 5/7; object-fit: contain; opacity: 1; transform: rotate(7deg); border: 7px solid var(--paper2); border-radius: 13px; box-shadow: -12px 12px 0 -4px #e8decc, -12px 12px 0 -3px var(--line), 0 22px 35px #3c302626; }
.art-caption { position: absolute; bottom: 0; text-align: center; font: italic 14px var(--serif); color: var(--muted); }
.practice-heading { margin-top: 0; }
.practice-heading h2 { margin: 7px 0 0; }
.practice-heading > .muted { font-size: 12px; }
.quick-grid { counter-reset: practice; gap: 14px; margin: 23px 0 42px; }
.quick { position: relative; counter-increment: practice; min-height: 174px; padding: 21px; border-radius: 12px; background: var(--paper2); border-color: transparent; }
.quick::before { content: '0' counter(practice); display: block; color: var(--muted); font: italic 16px var(--serif); margin-bottom: 25px; }
.quick::after { content: '↗'; position: absolute; top: 18px; right: 19px; color: var(--muted); }
.quick .emoji { display: none; }
.quick strong { font-size: 21px; line-height: 1.2; min-height: 51px; }
.quick small { display: block; margin-top: 12px; font-size: 11px; }
.quick.sage { background: var(--sage2); }
.quick.blue { background: #eef2f4; }
.quick.lilac { background: #f1edf1; }
.panel, .soft-panel { box-shadow: none; }
.card-day { grid-template-columns: 120px 1fr; padding: 24px; background: var(--paper2); }
.card-day h3 { font-size: 28px; }
.card-day .thumb-card { border-radius: 9px; }
.card-day .muted { max-width: 640px; }
.link-btn { font-size: 13px; }
.privacy-strip { background: transparent; border-top: 1px solid var(--line); border-radius: 0; padding: 23px 0 0; font-size: 13px; }
.bottom-nav { left: 50%; right: auto; bottom: 20px; transform: translateX(-50%); width: min(620px, calc(100% - 32px)); padding: 7px; border: 1px solid var(--line); border-radius: 18px; box-shadow: 0 10px 35px #3c302614; }
.bottom-inner { gap: 4px; }
.nav-btn { border-radius: 12px; padding: 8px 6px; min-height: 55px; font-size: 11px; }
.nav-btn .nav-ico { font-size: 18px; }
.nav-btn.active { background: var(--sage2); color: #3c503d; }
.nav-btn:hover { background: #eee9df; }
.state-grid, .sections-grid, .scenario-grid { gap: 18px; margin-top: 26px; }
.state-btn, .section-card, .scenario { background: var(--paper2); border-radius: 12px; padding: 24px; }
.state-btn:hover, .section-card:hover, .scenario:hover { transform: translateY(-3px); border-color: var(--sage); box-shadow: var(--shadow); }
.section-card .num { font-size: 36px; }
.scenario h3 { font-size: 25px; }
.deck-grid { gap: 27px 20px; margin-top: 12px; }
.deck-item img { border: 5px solid var(--paper2); border-radius: 10px; transition: transform .2s; }
.deck-item:hover img { transform: translateY(-5px) rotate(-1deg); }
.deck-item strong { font-family: var(--serif); font-size: 18px; font-weight: 400; margin-top: 12px; }
.search { padding: 15px 17px; border-radius: 10px; }
.chip, .tab { font-size: 13px; }
.chip.on { background: var(--sage2); border-color: var(--sage); }
.card-meta { padding-top: 15px; }
.question-box { background: var(--paper2); border: 0; border-left: 3px solid var(--gold); border-radius: 0 12px 12px 0; padding: 24px; }
.question-box p { margin-top: 10px; line-height: 1.5; }
.note-card { padding: 22px; border-radius: 12px; background: var(--paper2); }
.note-card h3 { font-size: 24px; }
.empty { border: 1px dashed var(--line); border-radius: 16px; background: var(--paper2); margin-top: 20px; }
details { background: var(--paper2); border-radius: 10px; margin: 13px 0; }
summary { padding: 22px; font-size: 22px; }
.details-body { padding: 0 22px 22px; }
.modal { align-items: center; backdrop-filter: blur(5px); }
.sheet { border-radius: 20px; padding: 30px; }
.toast { bottom: 110px; max-width: calc(100% - 32px); width: max-content; text-align: center; font-size: 14px; }
@media (max-width: 1000px) {
  .hero { gap: 22px; }
  .hero-copy .btn-row { align-items: stretch; flex-direction: column; max-width: 300px; }
  .quick { padding: 17px; }
  .quick strong { font-size: 19px; }
}
@media (max-width: 850px) {
  .hero { grid-template-columns: 1.15fr 1fr; }
  .hero-art { order: initial; min-height: 350px; }
  .hero-art img { width: 190px; }
  .quick-grid { grid-template-columns: repeat(2, 1fr); }
  .quick strong { min-height: 0; }
}
@media (max-width: 600px) {
  .topbar-inner { padding: 14px 18px; }
  .brand { font-size: 19px; gap: 9px; }
  .brand-mark { width: 32px; height: 38px; font-size: 24px; }
  .brand small { font-size: 8px; letter-spacing: .025em; }
  .privacy-badge { display: none; }
  main { padding: 22px 20px 125px; }
  .hero { grid-template-columns: 1fr; gap: 6px; padding: 0 0 28px; margin-bottom: 28px; }
  .hero-copy { padding: 8px 0; }
  .hero h1 { font-size: 48px; margin: 20px 0; }
  .hero-copy p { font-size: 14px; margin-bottom: 22px; }
  .hero-copy .btn-row { max-width: none; }
  .hero-art { min-height: 300px; padding-bottom: 32px; }
  .hero-art img { width: 170px; }
  .hero-orbit { max-width: 250px; }
  .art-caption { font-size: 12px; }
  .practice-heading > .muted { display: none; }
  .quick-grid { gap: 10px; margin: 19px 0 30px; }
  .quick { min-height: 170px; padding: 17px; }
  .quick::before { margin-bottom: 22px; }
  .quick strong { font-size: 19px; min-height: 46px; }
  .card-day { padding: 16px; gap: 17px; grid-template-columns: 90px 1fr; }
  .card-day h3 { font-size: 22px; }
  .card-day p { font-size: 13px; }
  .card-day .btn { padding: 10px 12px; min-height: 42px; }
  .bottom-nav { bottom: 0; width: 100%; border-radius: 16px 16px 0 0; padding: 7px 5px calc(7px + env(safe-area-inset-bottom)); }
  .nav-btn { font-size: 10px; }
  .state-grid, .sections-grid, .scenario-grid { grid-template-columns: 1fr; gap: 12px; }
  .state-btn { min-height: 90px; }
  .state-btn span { display: inline-block; margin: 0 15px 0 0; vertical-align: middle; }
  .deck-grid { gap: 22px 14px; }
  .deck-item strong { font-size: 17px; }
  .sheet { padding: 22px; }
  .note-card { padding: 15px; }
  .question-box { padding: 18px; }
}
@media (prefers-reduced-motion: reduce) {
  button:hover, .deck-item:hover img { transform: none; }
}
@media print {
  main { padding: 0; }
}

